use super::*;
#[derive(Debug,PartialEq,semio_framework_value::NativeReceive,semio_framework_value::RetireOwned)]
struct Datum{label:String,values:Vec<u32>}
impl NativeIntrinsicRecord for Datum{const INTRINSIC_FIELD_ID:u16=1;}
fn funded(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096,"actual intrinsic frontier {d:?}");RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn observe<R>(f:impl FnOnce()->R)->(R,(usize,usize)){let(r,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);assert!(!h.overflowed);(r,(h.requested_bytes,h.released_bytes))}
fn drain<V:RetireOwned>(value:V){let mut owner=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("intrinsic fixture has actual controlled retirement"));for _ in 0..10000{if owner.terminal_is_empty(){return;}let g=funded(owner.next_demand(4096).unwrap());let(s,h)=observe(||owner.step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}panic!("original intrinsic fixture close stalled");}
fn denied(g:RetainedCloneGrant,d:RetirementDemand)->Vec<RetainedCloneGrant>{let mut result=vec![RetainedCloneGrant{maximum_items:0,..g}];if d.copy_bytes>0{result.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g});}if d.capacity_bytes>0{result.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g});}if d.release_bytes>0{result.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g});}if d.depth>0{result.push(RetainedCloneGrant{maximum_depth:d.depth-1,..g});}result}
#[test]
fn native_intrinsic_record_receiving_preserves_original_custody_receipts_and_every_cancel_prefix(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let mut complete=0;for cut in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let value=DslValue::Object(vec![("label".into(),DslValue::String(law["document"]["label"].as_str().unwrap().into())),("values".into(),DslValue::Array(vec![DslValue::Number(semio_framework_value::Number::UInt(1)),DslValue::Number(semio_framework_value::Number::UInt(2)),DslValue::Number(semio_framework_value::Number::UInt(u32::MAX as u64))]))]);let mut source=Some(FieldValue::Record(RecordValue{fields:[(1,FieldValue::Value(value))].into_iter().collect()}));let mut receiver=NativeIntrinsicReceiving::<Datum>::default();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);let mut construction=semio_framework_value_native_owned::native_decoding::owned::OriginalConstructionFixture;let mut turns=0;while !receiver.is_ready()&&cut.is_none_or(|cut|turns<cut){let d=receiver.demands(&source,4096).unwrap();let g=funded(d);for grant in denied(g,d){let(p,h)=observe(||control.with_construction_recipient(&mut construction,|native|receiver.step(&mut source,native,4096,grant)).unwrap());assert_eq!(p,Default::default());assert_eq!(h,(0,0));assert_eq!(receiver.demands(&source,4096).unwrap(),d);}let(p,h)=observe(||control.with_construction_recipient(&mut construction,|native|receiver.step(&mut source,native,4096,g)).unwrap());assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));turns+=1;assert!(turns<10000);}
 if cut.is_none(){complete=turns;let mut output=None;let g=funded(metadata::<Option<Datum>>());let(p,h)=observe(||receiver.take_into(&mut output,g).unwrap());assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));let output=output.unwrap();assert_eq!(output.label,law["document"]["label"].as_str().unwrap());assert_eq!(output.values,[1,2,u32::MAX]);drain(output);}
 for _ in 0..10000{if receiver.terminal_is_empty(){break;}let d=receiver.close_demands(4096).unwrap();let g=funded(d);for grant in denied(g,d){let(p,h)=observe(||receiver.select_close(4096).unwrap().step(grant).unwrap().progress());assert_eq!(p,Default::default());assert_eq!(h,(0,0));assert_eq!(receiver.close_demands(4096).unwrap(),d);}let(p,h)=observe(||receiver.select_close(4096).unwrap().step(g).unwrap().progress());assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));}assert!(receiver.terminal_is_empty());assert_eq!(observe(||drop(receiver)).1,(0,0));if let Some(source)=source{drain(source);}}assert!(complete>0);}

#[test]fn selected_intrinsic_closure_requires_every_quoted_currency(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let demand=&law["selectedClosure"]["demand"];let n=|row:&serde_json::Value,key:&str|usize::try_from(row[key].as_u64().unwrap()).unwrap();let d=RetirementDemand{copy_bytes:n(demand,"copyBytes"),capacity_bytes:n(demand,"capacityBytes"),release_bytes:n(demand,"releaseBytes"),depth:n(demand,"depth")};for row in law["selectedClosure"]["cases"].as_array().unwrap(){let grant=&row["grant"];let g=RetainedCloneGrant{maximum_items:n(grant,"items"),maximum_copy_bytes:n(grant,"copyBytes"),maximum_capacity_bytes:n(grant,"capacityBytes"),maximum_release_bytes:n(grant,"releaseBytes"),maximum_depth:n(grant,"depth")};assert_eq!(funds(g,d),row["accepted"].as_bool().unwrap());}
}
